  "  const spy = vi.fn((x) => 'original ' + x)",
  "  vi.when(spy).calledWith(1).thenReturn('one')",
  "  expect(spy(1)).toBe('one')",
  "  expect(spy(2)).toBe('original 2')",
  "})",
].join("\n") + "\n");
