  process.exit(0);
}
if (r.out.includes("vi.when is not a function")) {
  console.error("FAIL: vi.when is not a function in this version");
  process.exit(1);
}
console.error("ERROR: unexpected result (exit " + r.status + ")");
process.exit(2);

